export type PartType = 'порог' | 'арка'

export interface Vehicle {
  brand: string
  model: string
  generation: string
}

export interface MaterialOption {
  id: string
  label: string
  note: string
  basePrices: Record<PartType, number>
  pairExtra: Partial<Record<PartType, number>>
}

export interface KitOption {
  id: string
  label: string
  note: string
  priceDelta: number
  pricingMode?: 'base-plus'
  sideExtra?: number
  materialExtra?: Partial<Record<string, number>>
  doublesBase?: boolean
  galvanizedExtra?: number
  fixedExtra?: number
}

export interface Part {
  id: string
  sku: string
  title: string
  type: PartType
  side: 'Комплект'
  vehicle: Vehicle
  /** Кузов из таблицы каталога (например, «Седан 4 дв.»). */
  body: string
  /** Годы выпуска из таблицы каталога. */
  years: string
  /** «Что производим на данную модель» из таблицы каталога. */
  produced: string[]
  basePrice: number
  images: string[]
  description: string
}

