export function producedKinds(produced: string[]): PartType[] {
  const kinds: PartType[] = []
  // Типы распознаём без учёта регистра: в каталоге встречаются варианты
  // «Внутренние пороги»/«Внутренний ПОРОГ» и «Задние арки»/«Арки».
  const lowered = produced.map((item) => item.toLowerCase())
  const has = (text: string) => lowered.some((item) => item.includes(text.toLowerCase()))
  if (has('порог')) kinds.push('порог')
  if (has('арк')) kinds.push('арка')
  return kinds
}

function slug(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9а-яё]+/gi, '-')
    .replace(/^-+|-+$/g, '')
}

export interface ArchDirectionOption {
  id: 'front' | 'rear'
  label: string
}

export const ARCH_DIRECTIONS: ArchDirectionOption[] = [
  { id: 'front', label: 'Передняя' },
  { id: 'rear', label: 'Задняя' },
]

/** Для арок с одновременными «Передние арки» и «Задние арки» в поле «Что производим». */
export function needsArchDirection(part: Part): boolean {
  return (
    part.type === 'арка' &&
    part.produced.some((item) => item.includes('Передние арки')) &&
    part.produced.some((item) => item.includes('Задние арки'))
  )
}

export function resolveArchDirectionId(directionId?: string): 'front' | 'rear' {
  return directionId === 'front' ? 'front' : 'rear'
}

export function archDirectionLabel(directionId?: string): string {
  return ARCH_DIRECTIONS.find((item) => item.id === resolveArchDirectionId(directionId))?.label ?? 'Задняя'
}

export function archDirectionTitle(part: Part, directionId?: string): string {
  if (part.type !== 'арка') return part.title
  if (!needsArchDirection(part)) return part.title
  const vehicleLabel = `${part.vehicle.brand} ${part.vehicle.model}`
  const label = archDirectionLabel(directionId)
  const years = part.years ? ` ${part.years}` : ''
  return `${label} колёсная арка для ${vehicleLabel}${years}`
}

const BASE_PRICE: Record<PartType, number> = { порог: 1790, арка: 1950 }

function buildPart(row: CatalogRow, kind: PartType): Part {
  const [brand, model, generation, years, body, title, sku, producedRaw] = row
  const produced = producedRaw.split(';').filter(Boolean)
  // Признаки направления тоже без учёта регистра («Задние арки»/«Арки» и т. п.).
  const producedLower = produced.map((item) => item.toLowerCase())
  const vehicleLabel = `${brand} ${model}`
  const hasRearArch = producedLower.some((item) => item.includes('задние арки'))
  const hasFrontArch = producedLower.some((item) => item.includes('передние арки'))
  const archScope = hasRearArch && hasFrontArch ? '' : hasFrontArch ? 'Передняя ' : hasRearArch ? 'Задняя ' : ''
  const label =
    kind === 'порог'
      ? `Порог ремонтный для ${vehicleLabel}`
      : hasRearArch && hasFrontArch
        ? `Колёсные арки для ${vehicleLabel}`
        : `${archScope}колёсная арка для ${vehicleLabel}`
  const generationNote = generation ? ` поколения «${generation}»` : ''
  const description =
    kind === 'порог'
      ? `Ремонтный порог для ${vehicleLabel}${generationNote}. Позиция из каталога: ${producedRaw.replace(/;/g, ', ')}${
          years ? `. Годы выпуска: ${years}` : ''
        }${body ? `, кузов: ${body}` : ''}.`
      : `Колёсная арка для ${vehicleLabel}${generationNote}. Позиция из каталога: ${producedRaw.replace(/;/g, ', ')}${
          years ? `. Годы выпуска: ${years}` : ''
        }${body ? `, кузов: ${body}` : ''}.`
  return {
    id: `${slug(brand)}-${slug(model)}-${slug(generation || 'all')}-${slug(body)}-${kind}`.slice(0, 96),
    sku,
    title: label,
    type: kind,
    side: 'Комплект',
    vehicle: { brand, model, generation: generation || 'все поколения' },
    body,
    years,
    produced,
    basePrice: BASE_PRICE[kind],
    images: [kind === 'порог' ? POROG_IMAGE : ARKA_IMAGE],
    description,
  }
}

// Preserve the first published URL when different catalogue entries share a
// vehicle/body label. Other entries get an article suffix so links, React keys
// and the cart identify the actual part rather than the first matching row.
const partIds = new Set<string>()
export const PARTS: Part[] = ROWS.flatMap((row) =>
  producedKinds(row[7].split(';').filter(Boolean)).map((kind) => {
    const part = buildPart(row, kind)
    if (partIds.has(part.id)) {
      const baseId = `${part.id}-${slug(part.sku)}`
      let id = baseId
      let suffix = 2
      while (partIds.has(id)) id = `${baseId}-${suffix++}`
      part.id = id
    }
    partIds.add(part.id)
    return part
  }),
)

/* URL-транслитерация кириллицы в латиницу (дружелюбные адреса каталога). */
const CYRILLIC_TO_LATIN: Record<string, string> = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'yo', ж: 'zh', з: 'z', и: 'i',
  й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't',
  у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '',
  э: 'e', ю: 'yu', я: 'ya',
}

/** Человеко-понятный фрагмент URL: транслитерация + дефисы вместо пробелов. */
export function toUrlSlug(value: string): string {
  return value
    .toLowerCase()
    .replace(/[а-яё]/g, (char) => CYRILLIC_TO_LATIN[char] ?? '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

// The CSV uses case/transliteration variants of the same brand (Lada/LADA,
// Volga/Волга). Use one filter value for each URL slug so every model remains
// selectable through a direct link. Keep article IDs and source titles intact.
const canonicalBrands = new Map<string, string>()
for (const part of PARTS) {
  const brandSlug = toUrlSlug(part.vehicle.brand)
  const canonical = canonicalBrands.get(brandSlug)
  if (canonical) part.vehicle.brand = canonical
  else canonicalBrands.set(brandSlug, part.vehicle.brand)
}

// The same normalization for models: «Hilux»/«HiLux», «Corolla Levin»/
// «corolla levin» and similar case variants must be one filter value, and
// identical products must land on one card. Brand+model are matched together
// because slug pairs of different models may coincide case-insensitively.
const canonicalModels = new Map<string, string>()
for (const part of PARTS) {
  const modelKey = `${toUrlSlug(part.vehicle.brand)}::${toUrlSlug(part.vehicle.model)}`
  const canonical = canonicalModels.get(modelKey)
  if (canonical) part.vehicle.model = canonical
  else canonicalModels.set(modelKey, part.vehicle.model)
}

// Merge only the same article, detail type and vehicle fitment. The CSV uses
// one SKU for both sills and arches, and sometimes for different vehicles.
// Preserve those distinct cards and their existing URLs.
const canonicalParts = new Map<string, Part>()
const mergedParts: Part[] = []
for (const part of PARTS) {
  const identity = JSON.stringify([part.sku, part.type, part.vehicle.brand, part.vehicle.model, part.vehicle.generation, part.body, part.years])
  const existing = canonicalParts.get(identity)
  if (!existing) {
    canonicalParts.set(identity, part)
    mergedParts.push(part)
    continue
  }
  const mergedKinds = new Set([...existing.produced, ...part.produced])
  existing.produced = Array.from(mergedKinds)
}
PARTS.splice(0, PARTS.length, ...mergedParts)

/** Тип детали → сегмент каталога в URL. */
export const TYPE_SLUGS: Record<string, string> = {
  все: 'porogi-i-arki',
  порог: 'porogi',
  арка: 'arki',
}

/** Обратное соответствие: сегмент URL → тип фильтра. */
export const TYPE_BY_SLUG: Record<string, 'все' | 'порог' | 'арка'> = {
  'porogi-i-arki': 'все',
  porogi: 'порог',
  arki: 'арка',
}

type CatalogSegment = {
  type: 'все' | 'порог' | 'арка'
  brand?: string
  model?: string
  generation?: string
}

/** Разбирает путь каталога вида /catalog/[тип]/[марка]/[модель]/[поколение]/. */
export function parseCatalogPath(segments: string[]): CatalogSegment | null {
  const [typeSlug, ...rest] = segments
  if (!typeSlug || rest.length > 3) return null
  const type = TYPE_BY_SLUG[typeSlug]
  if (!type) return null
  const [brandSlug, modelSlug, generationSlug] = rest
  if (!brandSlug) return { type }
  const brand = findPartValue(brandSlug, (part) => part.vehicle.brand)
  if (!brand) return null
  const result: CatalogSegment = { type, brand }
  if (modelSlug) {
    const model = findPartValue(
      modelSlug,
      (part) => (part.vehicle.brand === brand ? part.vehicle.model : ''),
    )
    if (!model) return null
    result.model = model
  }
  if (generationSlug) {
    if (!result.model) return null
    const generation = findPartValue(
      generationSlug,
      (part) =>
        part.vehicle.brand === brand && part.vehicle.model === result.model
          ? part.vehicle.generation
          : '',
    )
    if (!generation) return null
    result.generation = generation
  }
  return result
}

function findPartValue(slugValue: string, getValue: (part: Part) => string): string | null {
  for (const part of PARTS) {
    const value = getValue(part)
    if (value && toUrlSlug(value) === slugValue) return value
  }
  return null
}

/** Строит путь каталога из текущих фильтров: /catalog/[тип]/[марка]/[модель]/[поколение]/
 *  (фрагменты, равные значениям по умолчанию, пропускаются). */
export function buildCatalogPath(
  type: string,
  brand: string,
  model: string,
  generation: string,
): string {
  const segments = [TYPE_SLUGS[type] ?? TYPE_SLUGS['все']]
  if (brand) segments.push(toUrlSlug(brand))
  if (brand && model) segments.push(toUrlSlug(model))
  if (brand && model && generation) segments.push(toUrlSlug(generation))
  return `/catalog/${segments.join('/')}/`
}

export const VEHICLES: Vehicle[] = Array.from(
  new Map(
    PARTS.map((part) => [
      `${part.vehicle.brand}::${part.vehicle.model}::${part.vehicle.generation}`,
      part.vehicle,
    ]),
  ).values(),
)

export const BRANDS = Array.from(new Set(VEHICLES.map((v) => v.brand))).sort((a, b) =>
  a.localeCompare(b, 'ru'),
)

export function modelsForBrand(brand: string): string[] {
  return Array.from(
    new Set(VEHICLES.filter((v) => v.brand === brand).map((v) => v.model)),
  ).sort((a, b) => a.localeCompare(b, 'ru'))
}

export function generationsFor(brand: string, model: string): string[] {
  return VEHICLES.filter((v) => v.brand === brand && v.model === model).map((v) => v.generation)
}

export function partsForVehicle(brand: string, model: string, generation: string): Part[] {
  return PARTS.filter(
    (p) =>
      p.vehicle.brand === brand &&
      p.vehicle.model === model &&
      p.vehicle.generation === generation,
  )
}

export function findPart(id: string): Part | undefined {
  return PARTS.find((p) => p.id === id)
}

export function formatPrice(value: number): string {
  return `${new Intl.NumberFormat('ru-RU').format(value)} ₽`
}

export interface CartLine {
  partId: string
  materialId: string
  kitId: string
  /** Направление («Передняя»/«Задняя») для арок с двумя позициями в каталоге. */
  directionId?: string
  qty: number
}

export function kitsFor(type: PartType): KitOption[] {
  if (type === 'арка') return KITS_ARCH
  return [
    ...KITS,
    {
      id: 'full-repair',
      label: 'Ремонтный комплект',
      note:
        'Включает два порога, два усилителя порога и две торцевые заглушки. ' +
        'Цена = две стороны + 1800 ₽ за два усилителя порога + 1200 ₽ за две торцевые заглушки.',
      priceDelta: 0,
      doublesBase: true,
      galvanizedExtra: 600,
      fixedExtra: 3000,
    },
  ]
}

export function basePriceFor(part: Part, materialId: string): number {
  const material = MATERIALS.find((m) => m.id === materialId)
  return material?.basePrices[part.type] ?? part.basePrice
}

export function linePrice(part: Part, materialId: string, kitId: string): number {
  const material = MATERIALS.find((m) => m.id === materialId)
  const kit = kitsFor(part.type).find((k) => k.id === kitId)
  const base = basePriceFor(part, materialId)
  if (!kit) return base

  if (kit.pricingMode === 'base-plus') {
    let price = base + (kit.sideExtra ?? 0)
    if (kit.materialExtra) price += kit.materialExtra[materialId] ?? 0
    return price
  }

  if (!kit.doublesBase) return base

  let price = base * 2
  if (materialId === 'galvanized') price += material?.pairExtra[part.type] ?? 0
  price += kit.fixedExtra ?? 0
  return price
}

export function describeLine(line: CartLine): {
  part: Part
  material: MaterialOption
  kit: KitOption
  unitPrice: number
  sum: number
} | null {
  const part = findPart(line.partId)
  const material = MATERIALS.find((m) => m.id === line.materialId)
  const kit = kitsFor(part?.type ?? 'порог').find((k) => k.id === line.kitId)
  if (!part || !material || !kit) return null
  const unitPrice = linePrice(part, material.id, kit.id)
  return { part, material, kit, unitPrice, sum: unitPrice * line.qty }
}

export function cartTotal(lines: CartLine[]): number {
  return lines.reduce((sum, line) => {
    const described = describeLine(line)
    return sum + (described ? described.sum : 0)
  }, 0)
}
